CREATE TABLE IF NOT EXISTS economic_execution_outcomes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL, decision_id uuid NOT NULL, profile_id uuid NOT NULL, outcome_status text NOT NULL DEFAULT 'pending', outcome_summary text, outcome_score numeric(5,2), verified boolean NOT NULL DEFAULT false, recorded_by text NOT NULL, verified_by text, created_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz);
CREATE TABLE IF NOT EXISTS economic_learning_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outcome_id uuid NOT NULL, profile_id uuid NOT NULL, feedback_type text NOT NULL, signal_delta numeric(6,2), learning_summary text NOT NULL, trusted boolean NOT NULL DEFAULT false, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_execution_outcomes_execution ON economic_execution_outcomes(execution_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_learning_feedback_profile ON economic_learning_feedback(profile_id,created_at DESC);